/* Shared reporting semantics. Business records remain in their RLS-scoped source tables. */
function integrityDay(value){
 if(!value)return '';const s=String(value);if(/^\d{4}-\d{2}-\d{2}$/.test(s))return s;
 const d=new Date(value);return Number.isNaN(d.getTime())?'':new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);
}
function integrityRange(period='month',month=bangkokTodayISO().slice(0,7)){
 const today=bangkokTodayISO(),d=new Date(today+'T12:00:00Z');let from=today,to=today;
 if(period==='week'){const n=(d.getUTCDay()+6)%7;d.setUTCDate(d.getUTCDate()-n);from=d.toISOString().slice(0,10);d.setUTCDate(d.getUTCDate()+6);to=d.toISOString().slice(0,10);}
 if(period==='month'||period==='quarter'){
  if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month))throw new Error('กรุณาเลือกเดือนและปี');
  const [y,m]=month.split('-').map(Number),start=period==='quarter'?Math.floor((m-1)/3)*3:m-1,count=period==='quarter'?3:1;
  from=new Date(Date.UTC(y,start,1)).toISOString().slice(0,10);to=new Date(Date.UTC(y,start+count,0)).toISOString().slice(0,10);
 }return {from,to};
}
function integrityInRange(day,range){return !!day&&day>=range.from&&day<=range.to;}
function integrityWorkDate(t){return integrityDay(t.createdAt||t.startAt||(/^\d{4}-/.test(t.start||'')?t.start:''));}
function integrityReportRange(){return integrityRange(REP_PERIOD);}
