reportIssueRows=function(depts=reportDepts()){const range=integrityReportRange();return PROBLEMS.filter(p=>depts.includes(p.dept)&&integrityInRange(p.date,range));};
dashboardDueAt=function(t){
 if(t._deadline===false)return null;
 const raw=t.dueAt||t.due;if(!raw)return null;
 // A legacy MM-DD is ambiguous: don't invent its year. Date-only deadlines end in Bangkok.
 if(/^\d{2}-\d{2}$/.test(raw))return null;
 const d=new Date(/^\d{4}-\d{2}-\d{2}$/.test(raw)?raw+'T23:59:59.999+07:00':raw);return Number.isNaN(d.getTime())?null:d;
};
dashboardIsOverdue=function(t){const due=dashboardDueAt(t);return !!due&&t.status!=='done'&&due<new Date();};
function integrityOnTime(rows){const done=rows.filter(r=>r.status==='done'),known=done.filter(r=>dashboardDueAt(r)&&r.completedAt&&!Number.isNaN(new Date(r.completedAt).getTime()));return {total:done.length,known:known.length,missing:done.length-known.length,rate:known.length?Math.round(100*known.filter(r=>new Date(r.completedAt)<=dashboardDueAt(r)).length/known.length):null};}
function integrityOnTimeText(rows){const m=integrityOnTime(rows);return m.rate===null?'ยังประเมินตรงเวลาไม่ได้ · ข้อมูลไม่ครบ '+m.missing+' งาน':`ตรงเวลา ${m.rate}% จาก ${m.known} งานที่ข้อมูลครบ · ยังขาด ${m.missing} งาน`;}
async function integrityReadAll(factory,keys=['id']){
 const data=[];const pageSize=500;
 for(let offset=0;;offset+=pageSize){let query=factory();for(const key of keys)query=query.order(key,{ascending:true});const result=await query.range(offset,offset+pageSize-1);if(result.error)throw result.error;data.push(...(result.data||[]));if((result.data||[]).length<pageSize)return {data,error:null};}
}
sbAllRows=async function(table){return integrityReadAll(()=>SB.from(table).select('*'));};
