function integrityRefreshView(){TASKS.splice(0,TASKS.length,...TASKS.filter(t=>canViewDept(t.dept)));PROBLEMS.splice(0,PROBLEMS.length,...PROBLEMS.filter(p=>canViewDept(p.dept)));ACTIVITY_ROWS=ACTIVITY_ROWS.filter(r=>canViewDept(r.department_code));if(!canViewDept('GRAPHIC'))GRAPHIC_JOBS=[];if(document.querySelector('#native-activity-form')||document.querySelector('#report-draft-form'))return;if(['dash','board','teamBoard','reports','monthly','kpi','completeness','ann','tracker','activity','problems'].includes(VIEW))RENDER[VIEW](BOARD_DEPT);integrityRenderHealth();updateBell();}
function integrityWrapLoader(key,getSnapshot,restore,fn){DATA_HEALTH[key]={state:'idle'};let pending;return async function(...args){if(pending)return pending;pending=(async()=>{const snapshot=getSnapshot();DATA_HEALTH[key]={...DATA_HEALTH[key],state:'loading'};try{await fn(...args);DATA_HEALTH[key]={state:'ready',at:Date.now()};return true;}catch(e){restore(snapshot);DATA_HEALTH[key]={...DATA_HEALTH[key],state:'error',error:e.message};console.warn(key,e);return false;}finally{integrityRenderHealth();}})();try{return await pending;}finally{pending=null;}};}
cloudLoadTasks=integrityWrapLoader('tasks',()=>[TASKS.slice(),TASK_PROFILES.slice(),TASKS_READY],s=>{TASKS.splice(0,TASKS.length,...s[0]);TASK_PROFILES.splice(0,TASK_PROFILES.length,...s[1]);TASKS_READY=s[2];},cloudLoadTasks);
