activityReadinessData=function(){return DEPTS.filter(d=>canViewDept(d.code)).map(d=>{const graphic=d.code==='GRAPHIC',rows=graphic?GRAPHIC_JOBS:ACTIVITY_ROWS.filter(r=>r.department_code===d.code),dates=rows.map(r=>integrityDay(graphic?r.updated_at:r.activity_date)).filter(Boolean).sort();return {code:d.code,sheet:d.name,graphic,rows:rows.length,from:dates[0]||'',to:dates.at(-1)||'',review:rows.filter(r=>graphic?(!r.due_at||!r.assignee_id):activityReviewFlags(r).length).length,state:rows.length?'ready':'missing'};});};
function integrityScore(depts,range){const groups=depts.map(d=>KPI_CATALOG[d]||[]),valid=groups.filter(rows=>rows.length&&rows.every(k=>k.ac!==null&&k.pct!==null&&['approved','locked'].includes(k.status)&&k.period===`${range.from} – ${range.to}`)&&Math.abs(rows.reduce((s,k)=>s+k.w,0)-1)<1e-6);if(!valid.length)return null;return Math.round(valid.reduce((sum,rows)=>sum+rows.reduce((n,k)=>n+Math.min(100,k.pct)*k.w,0),0)/valid.length);}
