async function integritySaveDraft(){const button=document.getElementById('report-save'),error=document.getElementById('report-error');button.disabled=true;const body={};for(const k of Object.keys(REPORT_FIELDS))body[k]=document.getElementById('report-'+k).value;try{const r=await SB.rpc('save_report_draft',{p_period_start:REPORT_MONTH+'-01',p_departments:reportDepts().slice().sort(),p_expected_version:REPORT_DRAFT?.version||0,p_body:body});if(r.error)throw r.error;const saved=Array.isArray(r.data)?r.data[0]:r.data;if(!saved?.version)throw new Error('ไม่ได้รับการยืนยันบันทึก');REPORT_DRAFT=saved;REPORT_DRAFT_DIRTY=false;error.textContent='บันทึกลงฐานข้อมูลแล้ว · รุ่น '+saved.version;toast('บันทึกร่างรายงานแล้ว');}catch(e){error.textContent='ยังไม่บันทึก: '+e.message+' — ข้อความยังอยู่ในฟอร์ม กรุณาคัดลอกเก็บไว้ก่อนโหลดใหม่';}finally{button.disabled=false;}}
function integrityChangeReport(key,value){if(REPORT_DRAFT_DIRTY&&!confirm('มีข้อความที่ยังไม่บันทึก ต้องการเปลี่ยนรอบ/แผนกหรือไม่?')){const input=main.querySelector('input[type=month]');if(input)input.value=REPORT_MONTH;const select=main.querySelector('select');if(select)select.value=REP_DEPT;return;}if(key==='month')REPORT_MONTH=value;else REP_DEPT=value;REPORT_DRAFT_KEY='';REPORT_DRAFT=null;REPORT_DRAFT_DIRTY=false;RENDER.monthly();}
RENDER.monthly=function(skipLoad=false){const m=integrityReportModel(true),ready=REPORT_DRAFT_KEY===integrityDraftKey()&&REPORT_DRAFT;main.innerHTML=`${crumb('หน้าแรก','รายงานประจำเดือน')}<h1>รายงานประจำเดือน</h1><div class="filterbar"><label>เดือน–ปี <input class="fin" type="month" value="${REPORT_MONTH}" onchange="integrityChangeReport('month',this.value)"></label><label>แผนก<select class="fin" onchange="integrityChangeReport('dept',this.value)"><option value="">ทุกแผนกที่มีสิทธิ์</option>${DEPTS.filter(d=>canViewDept(d.code)).map(d=>`<option value="${d.code}" ${REP_DEPT===d.code?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label><button class="tbtn" onclick="exportMonthlyExcel()">CSV</button><button class="tbtn" onclick="printReport()">PDF / พิมพ์</button></div>${integrityReportHTML(m)}<section class="card pad"><h3>ร่างรายงานของฉัน</h3><p>แยกตามบัญชี เดือน และแผนก · บันทึกก่อนเปลี่ยนหน้า</p>${ready?`<form id="report-draft-form">${Object.entries(REPORT_FIELDS).map(([key,label])=>`<label>${label}<textarea class="fin" id="report-${key}" maxlength="10000" rows="3">${esc(REPORT_DRAFT.body[key]||'')}</textarea></label>`).join('')}<p id="report-error" role="status">รุ่นที่บันทึก ${REPORT_DRAFT.version}</p><button class="tbtn primary" id="report-save">บันทึกร่างลงฐานข้อมูล</button></form>`:'<p>กำลังเปิดร่างรายงาน… หากโหลดไม่สำเร็จ กดโหลดข้อมูลใหม่หรือเปิดหน้านี้อีกครั้ง</p>'}</section>`;if(ready){document.getElementById('report-draft-form').oninput=()=>{REPORT_DRAFT_DIRTY=true;};document.getElementById('report-draft-form').onsubmit=e=>{e.preventDefault();integritySaveDraft();};}else if(!skipLoad)integrityLoadDraft();integrityRenderHealth();};
exportMonthlyExcel=function(){const m=integrityReportModel(true),rows=integrityReportRows(m);rows.push([],['ร่างรายงาน']);for(const [k,label] of Object.entries(REPORT_FIELDS))rows.push([label,document.getElementById('report-'+k)?.value||REPORT_DRAFT?.body?.[k]||'']);downloadRows(rows,`monthly-${REPORT_MONTH}.csv`);};
window.addEventListener('beforeunload',e=>{if(REPORT_DRAFT_DIRTY){e.preventDefault();e.returnValue='';}});
// Completeness extends the existing owner/validation queue; no inferred assignments or dates.
const integrityCompleteness=RENDER.completeness;
RENDER.completeness=function(){integrityCompleteness();const rows=GRAPHIC_JOBS.filter(j=>j.status!=='done'&&(!j.due_at||!j.assignee_id)&&(canManageGraphic()||j.assignee_id===ACCESS_PROFILE?.id));main.insertAdjacentHTML('beforeend',`<section class="card pad"><h3>กราฟิกที่ต้องเติมวันส่ง / บัญชีเจ้าของ (${rows.length})</h3>${rows.slice(0,100).map(j=>`<p><b>${esc(j.title)}</b> · ${!j.due_at?'ขาดวันส่ง':''} ${!j.assignee_id?'ยังไม่ผูกบัญชีเจ้าของ':''} <button class="tbtn" onclick="openGraphicDue('${j.id}')">กำหนดวันส่ง</button><button class="tbtn" onclick="openGraphicJob('${j.id}')">เปิดรายละเอียด / เจ้าของ</button></p>`).join('')||'<p>ไม่มีรายการในขอบเขตนี้</p>'}</section>`);integrityRenderHealth();};
async function integrityAssignOwner(kind,id){const isGraphic=kind==='graphic',row=isGraphic?GRAPHIC_JOBS.find(r=>r.id===id):PROBLEMS.find(r=>r.id===id);if(!row)return;const dept=isGraphic?row.department_code:row.dept;const people=TASK_PROFILES.filter(p=>p.active&&p.department_code===dept);showModal(`<div class="modal-h"><h3>เลือกบัญชีเจ้าของงาน · ${esc(deptName(dept))}</h3><button class="x" onclick="closeModal()">×</button></div><form class="pad" id="assign-account-form"><p>เลือกจากบัญชีจริงในแผนก ชื่อเดิมและทีมรับผิดชอบยังคงอยู่</p><select class="fin" id="assign-account" required><option value="">เลือกบัญชี</option>${people.map(p=>`<option value="${p.id}">${esc(p.display_name||p.email)}</option>`).join('')}</select><p role="alert" id="assign-account-error"></p><button class="tbtn primary">บันทึกเจ้าของ</button></form>`);document.getElementById('assign-account-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const r=await SB.rpc(isGraphic?'assign_graphic_account':'assign_issue_account',{p_id:id,p_owner:val('assign-account'),p_expected_updated_at:isGraphic?row.updated_at:row.updatedAt});if(r.error)throw r.error;closeModal();await (isGraphic?loadGraphic():cloudLoadIssues());integrityRefreshView();toast('บันทึกบัญชีเจ้าของแล้ว');}catch(error){document.getElementById('assign-account-error').textContent=error.message;button.disabled=false;}};}
const integrityOpenGraphic=openGraphicJob;openGraphicJob=async function(id){await integrityOpenGraphic(id);if(canManageGraphic()&&document.querySelector('.modal-h')){const b=document.createElement('button');b.className='tbtn';b.textContent='มอบหมายบัญชี';b.onclick=()=>integrityAssignOwner('graphic',id);document.querySelector('.modal-h').append(b);}};
const integrityOpenProblem=openProblem;openProblem=function(id){integrityOpenProblem(id);const row=PROBLEMS.find(p=>p.id===id);if(row&&(canAdminAccess()||MANAGE_DEPTS.includes(row.dept))&&document.querySelector('.modal-h')){const b=document.createElement('button');b.className='tbtn';b.textContent='มอบหมายบัญชี';b.onclick=()=>integrityAssignOwner('issue',id);document.querySelector('.modal-h').append(b);}};
const integrityWorkPeople=teamWorkPeople;teamWorkPeople=function(work){if(work._source==='issue'&&work.sourceRow?.ownerProfileId)return [{key:'user:'+work.sourceRow.ownerProfileId,name:teamAccountName(work.sourceRow.ownerProfileId,work.assignee),linked:true}];return integrityWorkPeople(work);};
function integrityKpiAchievement(actual,target,metadata={}){if(actual==null||!Number.isFinite(Number(actual))||!Number.isFinite(Number(target)))return null;actual=Number(actual);target=Number(target);if(actual<0||target<0)return null;if(metadata.direction==='lower'){return actual===0?100:Math.min(100,100*target/actual);}if(target===0)return null;return Math.min(100,100*actual/target);}
loadWorkKpiReport=async function(box){try{const links=await sbAllRows('kpi_work_links','id');if(!box.isConnected)return;box.innerHTML='<h3>หลักฐานงานที่แท็ก KPI</h3><p>คลิกเปิดต้นทางเพื่อตรวจวันทำงานและผลลัพธ์ การแท็กไม่ให้คะแนนโดยอัตโนมัติ</p>'+Object.values(KPI_CATALOG).flat().map(d=>`<details><summary>${esc(d.n)} · ${links.data.filter(r=>r.definition_id===d.id).length} หลักฐาน</summary>${links.data.filter(r=>r.definition_id===d.id).map(r=>{const kind=r.activity_id?'activity':r.task_id?'task':r.graphic_job_id?'graphic':'issue',id=r.activity_id||r.task_id||r.graphic_job_id||r.issue_id;return `<button class="tbtn" data-evidence-kind="${kind}" data-evidence-id="${esc(id)}">${esc(BOARD_SOURCE_LABEL[kind])} #${esc(id)}</button>`;}).join('')||'<p>ยังไม่มีหลักฐาน</p>'}</details>`).join('');box.querySelectorAll('[data-evidence-kind]').forEach(b=>b.onclick=()=>{let id=b.dataset.evidenceId;if(b.dataset.evidenceKind==='task'){const task=TASKS.find(t=>t.dbId===id);if(!task){toast('ไม่พบงานในข้อมูลที่มีสิทธิ์ กรุณาโหลดใหม่','info');return;}id=task.id;}openBoardWork(b.dataset.evidenceKind,id);});}catch(e){box.textContent='อ่านหลักฐานไม่สำเร็จ · '+e.message;}};
const integrityKpiRender=RENDER.kpi;RENDER.kpi=function(){integrityKpiRender();const defs=Object.values(KPI_CATALOG).flat().filter(d=>canAdminAccess()||MANAGE_DEPTS.some(code=>KPI_CATALOG[code]?.includes(d)));if(defs.length){const section=document.createElement('section');section.className='card pad';section.innerHTML=`<h3>บันทึก / รับรองผล KPI รายเดือน</h3><p>หัวหน้าตรวจ Actual ตามสูตรและหลักฐานของรอบก่อนรับรอง คะแนนจะขึ้นเมื่อทั้งแผนกครบและน้ำหนักรวม 100%</p><label>เดือน <input type="month" class="fin" id="kpi-result-month" value="${bangkokTodayISO().slice(0,7)}"></label><select class="fin" id="kpi-result-definition">${defs.map(d=>`<option value="${d.id}">${esc(d.n)}</option>`).join('')}</select><button class="tbtn" id="kpi-result-open">เปิดผลรอบนี้</button>`;main.prepend(section);document.getElementById('kpi-result-open').onclick=()=>integrityOpenKpiResult(val('kpi-result-definition'),val('kpi-result-month'));}integrityRenderHealth();};
async function integrityOpenKpiResult(id,month){const range=integrityRange('month',month),def=Object.values(KPI_CATALOG).flat().find(d=>d.id===id);try{const result=await SB.from('kpi_results').select('*').eq('definition_id',id).eq('period_start',range.from).eq('period_end',range.to).maybeSingle();if(result.error)throw result.error;const row=result.data,locked=['approved','locked'].includes(row?.status);showModal(`<div class="modal-h"><h3>${esc(def.n)}</h3><button class="x" onclick="closeModal()">×</button></div><form class="pad" id="kpi-result-form"><p>${range.from} ถึง ${range.to} · ${esc(def.formula)}</p><label>Actual (หน่วยตามเกณฑ์; สัดส่วนกรอก 0–1)<input class="fin" id="kpi-actual" type="number" min="0" step="any" required value="${row?.actual??''}" ${locked?'readonly':''}></label><label>หลักฐานและวิธีคำนวณของรอบนี้<textarea class="fin" id="kpi-evidence" required ${locked?'readonly':''}>${esc(row?.evidence?.note||'')}</textarea></label><label>สถานะ<select class="fin" id="kpi-result-status">${(row?.status==='locked'?['locked']:row?.status==='approved'?['approved','locked']:['draft','review','approved']).map(s=>`<option value="${s}" ${row?.status===s?'selected':''}>${{draft:'ร่าง',review:'ส่งตรวจ',approved:'รับรองแล้ว',locked:'ล็อกรอบ'}[s]}</option>`).join('')}</select></label><p>หลังรับรองจะแก้ Actual และหลักฐานไม่ได้ ตรวจให้ครบก่อนบันทึก</p><p id="kpi-result-error" role="alert"></p><button class="tbtn primary" ${row?.status==='locked'?'disabled':''}>บันทึกผล</button></form>`);document.getElementById('kpi-result-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const r=await SB.rpc('save_monthly_kpi_result',{p_definition:id,p_period_start:range.from,p_actual:Number(val('kpi-actual')),p_note:val('kpi-evidence'),p_status:val('kpi-result-status'),p_expected_version:row?.version||0});if(r.error)throw r.error;closeModal();await cloudLoadKpis();RENDER.kpi();toast('บันทึกผล KPI แล้ว');}catch(error){document.getElementById('kpi-result-error').textContent=error.message;button.disabled=false;}};}catch(e){toast('เปิดผล KPI ไม่สำเร็จ · '+e.message,'info');}}
